:root {
  --bg: #1b1b2f;
  --card: #2e2e4a;
  --ink: #f6f1e9;
  --accent: #ffcc4d;
  --accent-pressed: #e0a800;
  --muted: #b8b4c9;
  --line: #6c6a8a;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 16px;
  background: var(--bg);
  background-image:
    linear-gradient(0deg, transparent 24%, rgba(255,255,255,0.03) 25%, rgba(255,255,255,0.03) 26%, transparent 27%, transparent 74%, rgba(255,255,255,0.03) 75%, rgba(255,255,255,0.03) 76%, transparent 77%),
    linear-gradient(90deg, transparent 24%, rgba(255,255,255,0.03) 25%, rgba(255,255,255,0.03) 26%, transparent 27%, transparent 74%, rgba(255,255,255,0.03) 75%, rgba(255,255,255,0.03) 76%, transparent 77%);
  background-size: 32px 32px;
  font-family: ui-monospace, 'Cascadia Code', 'Courier New', monospace;
  font-size: 16px;
  color: var(--ink);
}

.card {
  width: 100%;
  max-width: 400px;
  background: var(--card);
  border: 4px solid var(--ink);
  box-shadow: 8px 8px 0 var(--accent);
  padding: 24px;
}

h1 {
  margin: 0 0 4px;
  font-size: 1.75rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--bg);
}

.subtitle {
  margin: 0 0 24px;
  color: var(--muted);
  font-size: 0.9rem;
}

.field {
  margin-bottom: 20px;
  border: none;
  padding: 0;
}

label, legend {
  display: block;
  margin-bottom: 8px;
  font-weight: bold;
  font-size: 0.95rem;
  color: var(--ink);
}

input[type="number"] {
  width: 100%;
  padding: 12px;
  font-family: inherit;
  font-size: 1.1rem;
  color: var(--ink);
  background: var(--bg);
  border: 3px solid var(--line);
  outline: none;
}

input[type="number"]:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255, 204, 77, 0.35);
}

.tip-buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.tip-btn {
  padding: 12px 4px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  color: var(--ink);
  background: var(--bg);
  border: 3px solid var(--line);
  cursor: pointer;
  transition: transform 0.05s ease;
}

.tip-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.tip-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: var(--bg);
  border-color: var(--accent);
  box-shadow: inset 0 0 0 2px var(--bg);
}

.tip-btn:active {
  transform: translateY(2px);
  background: var(--accent-pressed);
}

.results {
  margin-top: 8px;
  border-top: 3px dashed var(--line);
  padding-top: 16px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 8px 0;
  gap: 12px;
}

.result-label {
  color: var(--muted);
  font-size: 0.95rem;
}

.result-value {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--ink);
}

.result-row.total .result-value {
  color: var(--accent);
}

.hint {
  margin: 16px 0 0;
  font-size: 0.85rem;
  color: var(--muted);
  min-height: 1.2em;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
    box-shadow: 6px 6px 0 var(--accent);
  }
  h1 { font-size: 1.5rem; }
  .result-value { font-size: 1.3rem; }
}

const billInput = document.getElementById('bill');
const peopleInput = document.getElementById('people');
const tipButtons = Array.from(document.querySelectorAll('.tip-btn'));
const tipPerPersonEl = document.getElementById('tipPerPerson');
const totalPerPersonEl = document.getElementById('totalPerPerson');
const hintEl = document.getElementById('hint');

let selectedTip = null;

function formatMoney(value) {
  return '$' + value.toFixed(2);
}

function update() {
  const bill = parseFloat(billInput.value);
  const people = parseInt(peopleInput.value, 10);

  if (isNaN(bill) || bill < 0) {
    tipPerPersonEl.textContent = '$0.00';
    totalPerPersonEl.textContent = '$0.00';
    hintEl.textContent = 'Enter a valid bill amount.';
    return;
  }

  if (isNaN(people) || people < 1) {
    tipPerPersonEl.textContent = '$0.00';
    totalPerPersonEl.textContent = '$0.00';
    hintEl.textContent = 'Number of people must be at least 1.';
    return;
  }

  if (selectedTip === null) {
    tipPerPersonEl.textContent = '$0.00';
    totalPerPersonEl.textContent = '$0.00';
    hintEl.textContent = 'Select a tip percent to see results.';
    return;
  }

  const tipTotal = bill * (selectedTip / 100);
  const total = bill + tipTotal;
  const tipPerPerson = tipTotal / people;
  const totalPerPerson = total / people;

  tipPerPersonEl.textContent = formatMoney(tipPerPerson);
  totalPerPersonEl.textContent = formatMoney(totalPerPerson);
  hintEl.textContent = '';
}

tipButtons.forEach(btn => {
  btn.addEventListener('click', () => {
    const value = parseFloat(btn.dataset.tip);
    selectedTip = value;
    tipButtons.forEach(b => b.setAttribute('aria-pressed', 'false'));
    btn.setAttribute('aria-pressed', 'true');
    update();
  });
});

billInput.addEventListener('input', update);
peopleInput.addEventListener('input', update);

// Initialize with 15% selected
const defaultBtn = tipButtons.find(b => b.dataset.tip === '15');
if (defaultBtn) {
  defaultBtn.click();
}
